// Normaliza las dos formas posibles de llegar aquí:
//   GET  /chat/session -> { data: { hasActiveSession, session } }
//   POST /chat/session -> { data: <la sesión directamente> }
const input = $input.first().json;
const payload = input.data ?? {};

const session = payload.session ?? (payload.sessionId ? payload : null);
const state = session?.conversationState ?? {};
const recipe = state.recipe ?? null;

return [{
  json: {
    sessionId: session?.sessionId ?? null,
    hasActiveSession: Boolean(session),
    previousRecipe: recipe,
    previousMedia: state.media ?? null,
    previousIntent: state.last_intent ?? null,
    previousMealType: state.metadata?.meal_type ?? null,
    previousGeneratedAt: state.metadata?.generated_at ?? null,
    version: Number(state.metadata?.version) || 1,
    // El pool de alimentos matcheados viaja dentro de recipe porque el
    // validador del backend descarta cualquier campo raíz desconocido.
    availableFoods: Array.isArray(recipe?.available_foods) ? recipe.available_foods : []
  }
}];

function extractJson(res, label) {
  const raw = res?.output?.[0]?.content?.[0]?.text
    ?? res?.message?.content
    ?? res?.text
    ?? res?.content;

  if (typeof raw !== 'string' || !raw.trim()) {
    throw new Error(`[${label}] El modelo no devolvió texto. Recibido: ${JSON.stringify(res).slice(0, 400)}`);
  }

  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start === -1 || end <= start) {
    throw new Error(`[${label}] No se encontró JSON en la respuesta: ${raw.slice(0, 400)}`);
  }

  try {
    return JSON.parse(raw.slice(start, end + 1));
  } catch (e) {
    throw new Error(`[${label}] JSON inválido (${e.message}): ${raw.slice(0, 400)}`);
  }
}

const VALID_INTENTS = [
  'GENERATE_RECIPE_WITH_INPUT',
  'GENERATE_RECIPE_FROM_FRIDGE',
  'MODIFY_RECIPE',
  'ASK_RECIPE',
  'NEW_RECIPE',
  'GENERAL_CHAT',
  'UNKNOWN'
];
const VALID_MEAL_TYPES = ['desayuno', 'almuerzo', 'cena'];

const parsed = extractJson($input.first().json, 'Interpretar Intención');
const session = $('Unificar Datos de Sesión').first().json;
const originalMessage = $('Extraer Datos del Request').first().json.message;

const ingredients = (Array.isArray(parsed.ingredients) ? parsed.ingredients : [])
  .filter(i => i && i.name)
  .map(i => ({
    name: String(i.name).toLowerCase().trim(),
    quantity: i.quantity === null || i.quantity === undefined || i.quantity === ''
      ? null
      : Number(i.quantity)
  }));

return [{
  json: {
    // Los datos de sesión siguen viajando: sin esto los guards de la ruta
    // no tienen con qué decidir.
    ...session,
    intent: VALID_INTENTS.includes(parsed.intent) ? parsed.intent : 'UNKNOWN',
    modificationType: parsed.modification_type ?? null,
    questionType: parsed.question_type ?? null,
    ingredients,
    mealType: VALID_MEAL_TYPES.includes(parsed.meal_type) ? parsed.meal_type : null,
    userRequest: parsed.user_request || originalMessage
  }
}];

const j = $input.first().json;
const attached = $('Extraer Datos del Request').first().json.attachedFoods ?? [];

const hasRecipe = Boolean(j.previousRecipe && j.previousRecipe.title);
const hasIngredients = Array.isArray(j.ingredients) && j.ingredients.length > 0;
const hasPool = Array.isArray(j.availableFoods) && j.availableFoods.length > 0;
const hasAttached = Array.isArray(attached) && attached.length > 0;

// Adjuntar un alimento no debe tumbar la receta en curso: si el usuario pidio
// modificarla o pregunto por ella, esa intencion gana sobre los adjuntos.
const INTENCIONES_DE_GENERACION = [
  'GENERATE_RECIPE_WITH_INPUT',
  'GENERATE_RECIPE_FROM_FRIDGE',
  'NEW_RECIPE',
  'UNKNOWN'
];

let route;
if (hasAttached && INTENCIONES_DE_GENERACION.includes(j.intent)) {
  route = 'RECIPE_FROM_ATTACHED';
} else {
  // Cada guard degrada a una ruta que si puede responder, en vez de romper.
  switch (j.intent) {
    case 'GENERATE_RECIPE_WITH_INPUT':
      route = hasIngredients ? 'RECIPE_FROM_INPUT' : 'RECIPE_FROM_FRIDGE';
      break;

    case 'GENERATE_RECIPE_FROM_FRIDGE':
      route = 'RECIPE_FROM_FRIDGE';
      break;

    case 'MODIFY_RECIPE':
      route = hasRecipe ? 'MODIFY_RECIPE' : 'RECIPE_FROM_FRIDGE';
      break;

    case 'ASK_RECIPE':
      route = hasRecipe ? 'ANSWER_QUESTION' : 'GENERAL_CHAT';
      break;

    case 'NEW_RECIPE':
      route = (hasRecipe && hasPool) ? 'NEW_RECIPE_SAME_POOL' : 'RECIPE_FROM_FRIDGE';
      break;

    default:
      route = 'GENERAL_CHAT';
  }
}

return [{
  json: {
    ...j,
    route,
    attachedFoods: attached,
    // El chef nombra lo pedido a partir de ingredients; con adjuntos sale de ahi.
    ingredients: route === 'RECIPE_FROM_ATTACHED'
      ? attached.map(f => ({
          name: String(f.name).toLowerCase().trim(),
          quantity: f.quantity ?? null
        }))
      : j.ingredients,
    // Si el usuario no repite el tipo de comida, se hereda del turno anterior.
    mealType: j.mealType ?? j.previousMealType ?? null
  }
}];

// GET /fridge devuelve items con name/quantity/unit pero SIN foodId,
// así que igual hay que pasarlos por /food/match para obtener los IDs.
const items = $input.first().json?.data?.items ?? [];

const ingredients = items
  .filter(i => i && i.name)
  .map(i => ({
    name: String(i.name).toLowerCase().trim(),
    quantity: Number(i.quantity) > 0 ? Number(i.quantity) : null
  }));

return [{
  json: {
    ingredients,
    fridgeItemCount: ingredients.length
  }
}];

// "Dame otra receta": se conserva el mismo pool de alimentos del turno
// anterior y se le dice al chef qué título NO repetir.
const j = $input.first().json;

return [{
  json: {
    availableFoods: j.availableFoods ?? [],
    avoidTitle: j.previousRecipe?.title ?? null
  }
}];

// Punto de convergencia de las tres rutas de generación.
// Deja siempre la misma forma para que el chef tenga un solo prompt.
const ctx = $('Resolver Ruta').first().json;
const input = $input.first().json;

// "Mapear Ingredientes a Alimentos"    -> { success, data: [...] }
// "Reusar Alimentos de Receta Previa"  -> { availableFoods: [...] }
const pool = Array.isArray(input.data)
  ? input.data
  : (Array.isArray(input.availableFoods) ? input.availableFoods : []);

// Un pool vacío no es un error del flujo: significa que ningún ingrediente
// coincidió con el catálogo. El IF siguiente lo desvía a una explicación.
const requested = (Array.isArray(ctx.ingredients) ? ctx.ingredients : [])
  .map(i => i.name)
  .filter(Boolean);

return [{
  json: {
    availableFoods: pool,
    foodCount: pool.length,
    requestedIngredients: requested,
    mealType: ctx.mealType ?? null,
    userRequest: ctx.userRequest ?? '',
    avoidTitle: input.avoidTitle ?? null
  }
}];

function extractJson(res, label) {
  const raw = res?.output?.[0]?.content?.[0]?.text
    ?? res?.message?.content
    ?? res?.text
    ?? res?.content;

  if (typeof raw !== 'string' || !raw.trim()) {
    throw new Error(`[${label}] El modelo no devolvió texto. Recibido: ${JSON.stringify(res).slice(0, 400)}`);
  }

  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start === -1 || end <= start) {
    throw new Error(`[${label}] No se encontró JSON en la respuesta: ${raw.slice(0, 400)}`);
  }

  try {
    return JSON.parse(raw.slice(start, end + 1));
  } catch (e) {
    throw new Error(`[${label}] JSON inválido (${e.message}): ${raw.slice(0, 400)}`);
  }
}

const parsed = extractJson($input.first().json, 'Chef de Cocina');
const chefContext = $('Preparar Contexto del Chef').first().json;
const pool = chefContext.availableFoods ?? [];

// El modelo no puede inventar foodId: se descarta lo que no esté en el pool.
const validIds = new Set(pool.map(f => Number(f.foodId)));
const ingredientsUsed = (Array.isArray(parsed.ingredients_used) ? parsed.ingredients_used : [])
  .map(i => ({
    food_id: Number(i.food_id),
    quantity: Number(i.quantity) > 0 ? Number(i.quantity) : 1
  }))
  .filter(i => validIds.has(i.food_id));

// Los pasos se normalizan aquí: la app hace un cast directo sobre step y
// description, así que no pueden llegar con otra forma.
const steps = (Array.isArray(parsed.steps) ? parsed.steps : [])
  .filter(s => s && typeof s === 'object')
  .map((s, idx) => ({
    step: Number(s.step) > 0 ? Number(s.step) : idx + 1,
    description: String(s.description ?? '').trim()
  }))
  .filter(s => s.description.length > 0);

const tips = (Array.isArray(parsed.tips) ? parsed.tips : [])
  .map(t => String(t).trim())
  .filter(t => t.length > 0);

return [{
  json: {
    responseType: 'RECIPE',
    recipe: {
      title: parsed.recipe_title ?? null,
      summary: parsed.recipe_summary ?? null,
      chef_reason: parsed.chef_reason ?? null,
      meal_type: parsed.meal_type ?? chefContext.mealType ?? null,
      difficulty: parsed.difficulty ?? null,
      preparation_time_minutes: Number(parsed.preparation_time_minutes) || null,
      servings: Number(parsed.servings) || null,
      estimated_calories: Number(parsed.estimated_calories) || null,
      tips,
      steps,
      ingredients_used: ingredientsUsed,
      // Se persiste para que MODIFY_RECIPE y NEW_RECIPE reutilicen los foodId
      // sin volver a llamar a /food/match.
      available_foods: pool
    }
  }
}];

