const parsed = extractJson($input.first().json, 'Búsqueda de Video');
const recipe = $('Parsear Receta del Chef').first().json.recipe;

const query = String(parsed.youtube_query ?? '').trim() || `receta ${recipe.title}`;

return [{ json: { youtubeQuery: query } }];

// Un fallo de YouTube (cuota agotada, sin resultados) no puede tumbar la receta.
const res = $input.first().json;
const item = Array.isArray(res?.items) ? res.items[0] : null;
const videoId = item?.id?.videoId;

if (!videoId) {
  return [{ json: { media: null } }];
}

const thumbnails = item.snippet?.thumbnails ?? {};

return [{
  json: {
    media: {
      youtube: {
        video_id: videoId,
        title: item.snippet?.title ?? null,
        channel: item.snippet?.channelTitle ?? null,
        thumbnail: thumbnails.high?.url ?? thumbnails.medium?.url ?? thumbnails.default?.url ?? null,
        url: `https://www.youtube.com/watch?v=${videoId}`
      }
    }
  }
}];

