const parsed = extractJson($input.first().json, 'Modificar Receta');
const ctx = $('Resolver Ruta').first().json;
const pool = ctx.availableFoods ?? [];
const previous = ctx.previousRecipe ?? {};

const validIds = new Set(pool.map(f => Number(f.foodId)));
const ingredientsUsed = (Array.isArray(parsed.ingredients_used) ? parsed.ingredients_used : [])
  .map(i => ({
    food_id: Number(i.food_id),
    quantity: Number(i.quantity) > 0 ? Number(i.quantity) : 1
  }))
  .filter(i => validIds.has(i.food_id));

// Misma normalización que en la ruta de generación: la app castea
// step y description sin red.
const normalizeSteps = (list) => (Array.isArray(list) ? list : [])
  .filter(s => s && typeof s === 'object')
  .map((s, idx) => ({
    step: Number(s.step) > 0 ? Number(s.step) : idx + 1,
    description: String(s.description ?? '').trim()
  }))
  .filter(s => s.description.length > 0);

const steps = normalizeSteps(parsed.steps);
const tips = (Array.isArray(parsed.tips) ? parsed.tips : [])
  .map(t => String(t).trim())
  .filter(t => t.length > 0);

return [{
  json: {
    responseType: 'RECIPE_MODIFIED',
    recipe: {
      title: parsed.recipe_title ?? previous.title ?? null,
      summary: parsed.recipe_summary ?? previous.summary ?? null,
      chef_reason: parsed.chef_reason ?? null,
      meal_type: parsed.meal_type ?? previous.meal_type ?? null,
      difficulty: parsed.difficulty ?? previous.difficulty ?? null,
      preparation_time_minutes: Number(parsed.preparation_time_minutes) || previous.preparation_time_minutes || null,
      servings: Number(parsed.servings) || previous.servings || null,
      estimated_calories: Number(parsed.estimated_calories) || previous.estimated_calories || null,
      tips: tips.length > 0 ? tips : (previous.tips ?? []),
      steps: steps.length > 0 ? steps : normalizeSteps(previous.steps),
      ingredients_used: ingredientsUsed.length > 0 ? ingredientsUsed : (previous.ingredients_used ?? []),
      available_foods: pool
    },
    // Se conserva el video del turno anterior: modificar porciones no cambia
    // el tutorial y así no se gasta cuota de YouTube.
    media: ctx.previousMedia ?? null
  }
}];

