const parsed = extractJson($input.first().json, 'Chat General');

return [{
  json: {
    responseType: 'CHAT',
    message: String(parsed.reply ?? '').trim() || '¡Hola! Dime qué tienes en la nevera y te armo una receta 🍳'
  }
}];

// Punto único de salida: todas las ramas producen el mismo envelope.
// El tipo lo declara cada rama en responseType, no se vuelve a mirar la ruta.
const j = $input.first().json;
const session = $('Unificar Datos de Sesión').first().json;
const route = $('Resolver Ruta').first().json;

// El backend rechaza cualquier otro valor.
const VALID_INTENTS = [
  'GENERATE_RECIPE_WITH_INPUT',
  'GENERATE_RECIPE_FROM_FRIDGE',
  'MODIFY_RECIPE',
  'ASK_RECIPE',
  'NEW_RECIPE'
];
const VALID_MEAL_TYPES = ['desayuno', 'almuerzo', 'cena'];

const type = j.responseType ?? 'CHAT';
const isRecipe = type === 'RECIPE' || type === 'RECIPE_MODIFIED';

const recipe = isRecipe ? (j.recipe ?? null) : null;
const media = isRecipe ? (j.media ?? null) : null;

const message = isRecipe
  ? (recipe?.chef_reason || recipe?.summary || `Te preparé: ${recipe?.title}`)
  : (j.message || 'Listo.');

const now = new Date().toISOString();
const servings = Number(recipe?.servings);
const nextVersion = isRecipe ? session.version + 1 : session.version;

return [{
  json: {
    response: {
      type,
      message,
      recipe,
      media,
      session: {
        sessionId: session.sessionId,
        version: nextVersion
      }
    },
    shouldPersistRecipe: isRecipe,
    persist: {
      last_intent: VALID_INTENTS.includes(route.intent) ? route.intent : null,
      meal_type: VALID_MEAL_TYPES.includes(recipe?.meal_type) ? recipe.meal_type : null,
      servings: Number.isInteger(servings) && servings > 0 ? servings : null,
      generated_at: type === 'RECIPE_MODIFIED' ? (session.previousGeneratedAt || now) : now,
      last_modified_at: now,
      version: nextVersion
    }
  }
}];

