const chef = $('Preparar Contexto del Chef').first().json;
const names = Array.isArray(chef.requestedIngredients) ? chef.requestedIngredients : [];

const message = names.length > 0
  ? `No encontré ${names.join(', ')} en el catálogo de alimentos 😕 Agrégalos desde la sección Alimentos y lo volvemos a intentar, o dime otros que tengas.`
  : 'No pude reconocer los alimentos de tu nevera en el catálogo 😕 Revisa que estén bien registrados en la sección Alimentos.';

return [{ json: { responseType: 'CHAT', message } }];

// Los adjuntos ya vienen con foodId y cantidad resueltos por el backend,
// asi que el pool del chef se arma sin pasar por /food/match.
const attached = $json.attachedFoods ?? [];

return [{
  json: {
    availableFoods: attached.map(f => ({
      foodId: f.foodId,
      name: f.name,
      caloriesPerUnit: f.caloriesPerUnit,
      baseUnit: f.baseUnit,
      quantity: f.quantity
    }))
  }
}];
